# INPUT 4 (part D): consequence workflow on REAL chrX GTF with annotated CDS (ISAR addAnnotatedORFs default): Skill order (extractSequence before analyzeORF) IS valid here.
# Independent check of ISAR's NMD/PTC call against Ensembl's own transcript biotype ("nonsense_mediated_decay") and a hand computation from CDS/exon coordinates.
setwd("F:/OpenScience/audits/bio-isoform-switching/run/work"); source("../helpers.R")
suppressPackageStartupMessages({ library(IsoformSwitchAnalyzeR); library(tximport) })
sm <- c("ERR188383", "ERR188428", "ERR188454", "ERR204916"); design <- data.frame(sampleID = sm, condition = c("GBR", "GBR", "YRI", "YRI"))
PD <- "F:/OpenScience/audit-envs/alternative-splicing/public-data"
file.copy(file.path(PD, "rnasplice/reference/genes_chrX.gtf"), "annotation.gtf", overwrite = TRUE); file.copy(file.path(PD, "derived/chrX_tx.fa"), "transcripts.fa", overwrite = TRUE)
txi <- suppressMessages(tximport(setNames(file.path("real_salmon", sm, "quant.sf"), sm), type = "salmon", txOut = TRUE, countsFromAbundance = "no"))
cn <- data.frame(isoform_id = rownames(txi$counts), txi$counts, check.names = FALSE); ab <- data.frame(isoform_id = rownames(txi$abundance), txi$abundance, check.names = FALSE)
sl <- suppressWarnings(importRdata(cn, ab, design, "annotation.gtf", "transcripts.fa", showProgress = FALSE, quiet = TRUE))
o <- sl$orfAnalysis; cat("annotated ORFs imported from GTF CDS:", if (is.null(o)) 0 else nrow(o), "\n"); print(head(o[, c("isoform_id", "orfTransciptStart", "orfTransciptEnd", "stopDistanceToLastJunction", "PTC", "orf_origin")], 3))
chk("importRdata() annotated ORFs from the GTF CDS lines (addAnnotatedORFs default)", !is.null(o) && nrow(o) > 1000, sprintf("%d ORFs", if (is.null(o)) 0 else nrow(o)))
# --- independent check 1: Ensembl biotype (column 2 of 'transcript' lines)
tid_of <- function(x) vapply(regmatches(x, regexec('transcript_id "([^"]+)"', x)), function(m) m[2], "")
g <- read.delim("annotation.gtf", header = FALSE, stringsAsFactors = FALSE, quote = "", comment.char = "")
tl <- g[g$V3 == "transcript", ]; tl$tid <- tid_of(tl$V9); bt <- setNames(tl$V2, tl$tid)
o$biotype <- bt[o$isoform_id]; o <- o[!is.na(o$biotype), ]
tab <- table(ISAR_PTC = o$PTC, Ensembl_NMD_biotype = o$biotype == "nonsense_mediated_decay"); print(tab)
sens <- tab["TRUE", "TRUE"] / sum(tab[, "TRUE"]); spec <- tab["FALSE", "FALSE"] / sum(tab[, "FALSE"])
cat(sprintf("ISAR PTC flag vs Ensembl NMD biotype: sensitivity %.2f (%d/%d), specificity %.2f\n", sens, tab["TRUE", "TRUE"], sum(tab[, "TRUE"]), spec))
chk("ISAR PTC flag agrees with Ensembl NMD biotype (sensitivity >= 0.8, specificity >= 0.95)", sens >= 0.8 && spec >= 0.95, sprintf("sens %.2f spec %.2f", sens, spec))
# --- independent check 2: hand-computed distance from stop codon to last junction from exon coordinates for 3 random NMD-flagged transcripts (+ strand only)
ex <- g[g$V3 == "exon", ]; ex$tid <- tid_of(ex$V9)
sc <- g[g$V3 == "stop_codon", ]; sc$tid <- tid_of(sc$V9)
set.seed(2); chosen <- head(intersect(o$isoform_id[o$PTC], sc$tid[sc$V7 == "+"]), 200); chosen <- sample(chosen, min(5, length(chosen)))
res <- sapply(chosen, function(t) { e <- ex[ex$tid == t, ]; e <- e[order(e$V4), ]; last_j <- e$V4[nrow(e)]   # genomic start of last exon = last junction (+ strand)
  stop_end <- sc$V5[sc$tid == t][1]; c(hand = sum(pmax(0, pmin(e$V5, last_j - 1) - pmax(e$V4, stop_end + 1) + 1)), isar = o$stopDistanceToLastJunction[o$isoform_id == t]) })
print(t(res)); chk("ISAR stopDistanceToLastJunction == hand-computed spliced distance (+ strand, 5 NMD-flagged real transcripts)", all(res["hand", ] == res["isar", ]), paste(res["hand", ], res["isar", ], sep = "/", collapse = " "))
# --- Skill workflow order: extractSequence BEFORE analyzeORF
sl <- preFilter(sl, geneExpressionCutoff = 1, isoformExpressionCutoff = 0, IFcutoff = 0.01, removeSingleIsoformGenes = TRUE, keepIsoformInAllConditions = TRUE, quiet = TRUE)
sl <- isoformSwitchTestDEXSeq(sl, reduceToSwitchingGenes = TRUE, alpha = 0.05, dIFcutoff = 0.1, quiet = TRUE)
cat("genes kept:", length(unique(sl$isoformFeatures$gene_id)), "\n")
dir.create("seq_real", showWarnings = FALSE)
sl <- tryCatch(extractSequence(sl, pathToOutput = "seq_real/", writeToFile = TRUE, quiet = TRUE), error = function(e) { cat("ERROR:", conditionMessage(e), "\n"); NULL })
chk("Skill order (extractSequence before analyzeORF) works when the GTF carries CDS lines", !is.null(sl), if (is.null(sl)) "failed" else "ok"); print(list.files("seq_real"))
saveRDS(sl, "real_after_seq.rds")
cat("DONE 36a\n")
